def standard():
    x = symbols('x')
    def den_roots(k):
        rs = []
        for r in roots(Poly(x**2 - (k + 1)*x + 4, x), multiple=True):
            if r.is_real and r >= 0: rs.append(r)
        for r in roots(Poly(x**2 + (k - 1)*x + 4, x), multiple=True):
            if r.is_real and r < 0: rs.append(r)
        return rs
    def order(p, r):
        m = 0
        while simplify(p.subs(x, r)) == 0:
            m += 1; p = diff(p, x)
        return m
    def works(g, k):
        rs = den_roots(k)
        return all(order((x + 2)**2*g, r) >= rs.count(r) for r in set(rs))
    found = []
    for k1 in range(3, 12):
        for k2 in range(k1 + 1, 12):
            need = {}
            for k in (k1, k2):
                rs = den_roots(k)
                for r in set(rs):
                    m = rs.count(r) - (2 if r == -2 else 0)
                    if m > 0: need[r] = max(need.get(r, 0), m)
            if sum(need.values()) != 4: continue
            g = Mul(*[(x - r)**m for r, m in need.items()])
            c = Rational(10)/g.subs(x, 2) if g.subs(x, 2) != 0 else None
            if c is None: continue
            g = expand(c*g)
            if sum(1 for k in range(1, 40) if works(g, k)) == 4:
                found.append(simplify(g.subs(x, 6)))
    assert len(set(found)) == 1
    return found[0]

