def standard():
    x = symbols('x')
    T = lambda v: 4*v - 3 if v >= 0 else v/2 + 1
    cands = set()
    # all itineraries of length <= 3 (signs), solve fixed point of composition
    for L in (1, 2, 3):
        for signs in itertools.product([1, -1], repeat=L):
            v = x
            for sg in signs:
                v = 4*v - 3 if sg > 0 else v/2 + 1
            sol = solve(Eq(v, x), x)
            for s0 in sol:
                orbit = [s0]
                ok = True
                cur = s0
                for sg in signs:
                    if (sg > 0 and cur < 0) or (sg < 0 and cur > 0):
                        ok = False; break
                    cur = T(cur); orbit.append(cur)
                if ok and cur == s0:
                    cands.add(tuple(sorted(set(orbit))))
    res = set()
    k = symbols('k', positive=True)
    for orb in cands:
        if len(orb) != 3 or 1 in orb or -1 in orb:
            continue
        f = k*Mul(*[(x - r) for r in orb])
        k0 = solve(Eq(f.subs(x, -1)*f.subs(x, 1), -96), k)
        for kv in k0:
            res.add(2*f.subs(k, kv).subs(x, 2))
    assert len(res) == 1
    return res.pop()

