def standard():
    x = symbols('x')
    k = symbols('k')
    res = set()
    # case r=-2: g_left = k x (x+2)^3, g_right = x (x-2)(x-s)
    for sv in [Rational(n, 4) for n in range(-40, 1)]:
        ks = solve(Eq((k*(-1)*1**3)*(1*(1 - 2)*(1 - sv)), -Rational(1, 2)), k)
        for kv in ks:
            if not kv.is_real: continue
            gl = kv*x*(x + 2)**3; gr = x*(x - 2)*(x - sv)
            f = kv*x*(x + 2)
            den = f.subs(x, x - 2)
            lim_l = limit(gl/den, x, 0, '-'); lim_r = limit(gr/den, x, 0, '+')
            if simplify(lim_l - lim_r) != 0: continue
            # sign changes at nonzero roots
            ch = set()
            for r in [-2]:
                ch.add(r)
            for r in set(solve(gr, x)):
                if r > 0 and gr.subs(x, r - Rational(1, 1000))*gr.subs(x, r + Rational(1, 1000)) < 0:
                    ch.add(r)
            if len(ch) == 2 and sum(ch) == 0:
                res.add(gl.subs(x, -4) + gr.subs(x, 5))
    assert len(res) == 1
    return res.pop()

