    c3, c2, c1, c0 = symbols('c3 c2 c1 c0')
    f = c3*x**3 + c2*x**2 + c1*x + c0
    sol = solve([f.subs(x, 0), diff(f, x).subs(x, 0), f.subs(x, 1) + 3, f.subs(x, 3) + 9], [c3, c2, c1, c0], dict=True)[0]
    F = f.subs(sol)
    q = max(solve(diff(F, x), x))
    def g(v):
        return F.subs(x, v) - 6 if diff(F, x).subs(x, v) <= 0 else F.subs(x, v)
    cand = set()
    e = Rational(1, 10**6)
    for r in solve(Eq(F, -9), x) + solve(Eq(F, -3), x) + [Integer(0), q]:
        if not r.is_real: continue
        if abs(float(g(r - e) + g(r + e) - 4*g(r) - 18)) < 1e-3:
            cand.add(r)
    cand = sorted(cand, key=lambda v: float(v))
    assert [float(v) for v in cand[1:]] == [0.0, 1.0, 3.0]
    return simplify(cand[0])

