def standard():
    x = symbols('x')
    res = set()
    for d in range(1, 6):
        for m5 in range(0, d + 1):
            for m7 in range(0, d + 1 - m5):
                for m8 in range(0, d + 1 - m5 - m7):
                    extra = d - m5 - m7 - m8
                    g = lambda n, m: min(m, n//d)
                    if g(5, m5) < 1: continue
                    if g(7, m7) + g(8, m8) != 3: continue
                    if extra != 0:
                        raise ValueError('extra root family also fits')
                    base = (x - 5)**m5*(x - 7)**m7*(x - 8)**m8
                    c = Rational(2)/(base.subs(x, 6)*g(5, m5))
                    res.add((c*base).subs(x, 4))
    assert len(res) == 1
    return res.pop()

